-- ==============================================================================
-- Join codes are 5-digit numbers (e.g. 48213) generated by the database.
-- Hosts can't choose or change them; guests join with /user/<code> or the QR code.
-- The internal event id (uuid) is unchanged, so posts, votes and R2 file paths are unaffected.
-- ==============================================================================

-- 1. Unique random 5-digit code (10000-99999)
CREATE OR REPLACE FUNCTION public.generate_join_code()
RETURNS text
LANGUAGE plpgsql
VOLATILE
SET search_path = public
AS $$
DECLARE
  candidate text;
BEGIN
  LOOP
    candidate := (floor(random() * 90000) + 10000)::int::text;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM events WHERE join_code = candidate);
  END LOOP;
  RETURN candidate;
END;
$$;

-- 2. Give existing events a 5-digit code (one row at a time so each new code is visible to the next check)
DO $$
DECLARE
  ev record;
BEGIN
  FOR ev IN SELECT id FROM public.events WHERE join_code !~ '^[0-9]{5}$' LOOP
    UPDATE public.events SET join_code = public.generate_join_code() WHERE id = ev.id;
  END LOOP;
END $$;

-- 3. Only 5-digit codes are valid from now on
ALTER TABLE public.events DROP CONSTRAINT IF EXISTS events_join_code_5_digits;
ALTER TABLE public.events ADD CONSTRAINT events_join_code_5_digits CHECK (join_code ~ '^[0-9]{5}$');
ALTER TABLE public.events ALTER COLUMN join_code SET DEFAULT public.generate_join_code();

-- 4. The database always assigns the code on insert (any client-supplied value is ignored)
CREATE OR REPLACE FUNCTION public.assign_join_code()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  NEW.join_code := public.generate_join_code();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS events_assign_join_code ON public.events;
CREATE TRIGGER events_assign_join_code
  BEFORE INSERT ON public.events
  FOR EACH ROW EXECUTE FUNCTION public.assign_join_code();

-- 5. ...and it can never be changed afterwards
CREATE OR REPLACE FUNCTION public.prevent_join_code_change()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF NEW.join_code IS DISTINCT FROM OLD.join_code THEN
    RAISE EXCEPTION 'The join code of an event cannot be changed';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS events_join_code_immutable ON public.events;
CREATE TRIGGER events_join_code_immutable
  BEFORE UPDATE OF join_code ON public.events
  FOR EACH ROW EXECUTE FUNCTION public.prevent_join_code_change();
